const CACHE_NAME = 'nix-builds-static-v2.5.14';
const STATIC_ASSETS = ['/manifest.webmanifest', '/icon.svg', '/sw.js'];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => cache.addAll(STATIC_ASSETS)).then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys => Promise.all(
      keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k))
    )).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Never cache HTML navigations. Product pages and routes are generated by the
  // Cloudflare Worker and must always be allowed to reach the network.
  if (req.mode === 'navigate' || req.destination === 'document') {
    event.respondWith(fetch(req));
    return;
  }

  // Cache only small static PWA assets. Other assets use normal network behavior.
  if (STATIC_ASSETS.includes(url.pathname)) {
    event.respondWith(
      caches.match(req).then(cached => cached || fetch(req).then(response => {
        const copy = response.clone();
        caches.open(CACHE_NAME).then(cache => cache.put(req, copy));
        return response;
      }))
    );
  }
});
